INSERT INTO `paper` (`id`,`aminer_id`,`title`,`abstract`,`keywords`,`authors`,`venue`,`year`,`citation_count`,`embedding`,`deleted`,`create_time`,`update_time`) VALUES (485,'aminer_485','Adaptive Schema Matching in Column-Store Database Systems','This paper explores Column-Store methods for Schema Matching in analytical database systems. Our technique reduces memory footprint while maintaining query accuracy within strict bounds.','["database","OLTP","OLAP","learned index"]','["Jakob Luo","Yoshua Lin","Yann Chen","Zhi Jordan"]','AAAI',2019,42537,NULL,0,NOW(),NOW());
INSERT INTO `paper` (`id`,`aminer_id`,`title`,`abstract`,`keywords`,`authors`,`venue`,`year`,`citation_count`,`embedding`,`deleted`,`create_time`,`update_time`) VALUES (486,'aminer_486','Cross-Domain Click-Through Rate Prediction Using Transformer Transfer','This paper proposes a Transformer model for Click-Through Rate Prediction that addresses data sparsity and cold-start challenges. Our method outperforms state-of-the-art baselines on multiple benchmark datasets.','["personalization","recommendation system","matrix factorization","cold start","deep learning"]','["Daniel Sutton","Robert Parikh"]','ICRA',2018,38562,NULL,0,NOW(),NOW());
