INSERT INTO `paper` (`id`,`aminer_id`,`title`,`abstract`,`keywords`,`authors`,`venue`,`year`,`citation_count`,`embedding`,`deleted`,`create_time`,`update_time`) VALUES (488,'aminer_488','Sample-Efficient Model-Based Planning with Transformer-Based','We introduce a Transformer-Based algorithm for Model-Based Planning that significantly improves sample efficiency. Experiments on Atari and MuJoCo benchmarks show substantial gains over prior methods.','["actor-critic","reward","exploration","DQN","reinforcement learning"]','["David Gil"]','ICSE',2025,10444,NULL,0,NOW(),NOW());
